using System.Text.Json.Nodes;
namespace StarlightSyndicateDemo;
public static class IndustryTests37
{
 public static void Run()
 {
  int count=0;void Check(bool pass,string message){if(!pass)throw new Exception("INDUSTRY37 FAIL: "+message);count++;Console.WriteLine("PASS "+message);}
  SkillCatalog.VerificationAllV=false;var world=new DemoWorld();world.NewGame(0);world.Credits=100000000;world.Skills.Grant(SkillCatalog.All.Select(s=>new SkillRequirement(s.Id,5)));
  var recipes=IndustryCatalog37.Recipes;Check(ItemCatalog.All.All(i=>recipes.ContainsKey(i.Id)),"every catalogue item has a blueprint and mineral recipe");Check(recipes.Values.All(r=>r.Minerals.Count>0&&r.Minerals.All(m=>m.Value>0&&ItemCatalog.All.Any(i=>i.Id==m.Key))),"positive mineral recipes reference real materials");Check(recipes.Values.All(r=>r.Native.All(m=>ItemCatalog.All.Any(i=>i.Id==m.Key))),"all CCP recipe dependencies resolve to available catalogue items");Check(recipes.Values.All(r=>IndustryCatalog37.BuildSkills(r,false).Length>0),"every mineral fabrication has build requirements");Check(IndustryCatalog37.Database.Blueprints.Count>4800,"current CCP manufacturing database imported");
  var ammo=recipes["ammo"];var bp=world.Industry.Blueprints.First(b=>b.Item=="ammo");
  void Supply(IndustryRecipe37 r,bool native,int runs){foreach(var m in IndustryCatalog37.Materials(r,native,runs,bp.ME,1))world.Hangar[m.Key]=m.Value+1000;}
  Supply(ammo,false,5);var q=world.QuoteIndustry(bp.Id,IndustryActivity.Manufacturing,5);Check(q.Error==""&&q.Inputs.Count>0&&q.Seconds>0&&q.Fee>0,"manufacturing quote validates inputs and includes duration and installation cost");var before=world.Balance;decimal prior=world.Hangar.GetValueOrDefault("ammo");Check(world.InstallIndustry(bp.Id,IndustryActivity.Manufacturing,5)=="","manufacturing installs");var job=world.Industry.Jobs.Last();Check(bp.LockedJob==job.Id&&world.Balance<before,"installation consumes fee and locks blueprint");Check(world.Hangar.GetValueOrDefault("ammo")==prior,"installation does not produce early output");Check(world.InstallIndustry(bp.Id,IndustryActivity.Copying)!="","locked blueprint rejects concurrent copying");Check(world.DeliverIndustry(job.Id)!="","early delivery rejected");job.FinishUtc=DateTime.UtcNow.AddSeconds(-1);Check(world.DeliverIndustry(job.Id)==""&&world.Hangar["ammo"]==prior+5*ammo.Definition.Output,"manufactured output is delivered in correct batches");Check(world.DeliverIndustry(job.Id)!="","delivery is idempotent");
  Check(world.InstallIndustry(bp.Id,IndustryActivity.MaterialResearch,target:10)=="","ME research installs to target");job=world.Industry.Jobs.Last();job.FinishUtc=DateTime.UtcNow.AddSeconds(-1);world.DeliverIndustry(job.Id);Check(bp.ME==10,"ME caps at 10 percent");Check(world.InstallIndustry(bp.Id,IndustryActivity.MaterialResearch,target:11)!="","ME above cap rejected");Check(world.InstallIndustry(bp.Id,IndustryActivity.TimeResearch,target:10)=="","TE research installs");job=world.Industry.Jobs.Last();job.FinishUtc=DateTime.UtcNow.AddSeconds(-1);world.DeliverIndustry(job.Id);Check(bp.TE==20,"TE ten levels grant 20 percent reduction");
  Check(world.InstallIndustry(bp.Id,IndustryActivity.Copying,3,2)=="","copying installs number of copies and runs per copy");job=world.Industry.Jobs.Last();job.FinishUtc=DateTime.UtcNow.AddSeconds(-1);world.DeliverIndustry(job.Id);var copies=world.Industry.Blueprints.Where(b=>!b.Original&&b.Item=="ammo").ToArray();Check(copies.Length==2&&copies.All(b=>b.Runs==3&&b.ME==10&&b.TE==20),"copies inherit ME TE and finite run limits");var copy=copies[0];Check(world.InstallIndustry(copy.Id,IndustryActivity.MaterialResearch)!="","copies cannot be researched");Check(world.InstallIndustry(copy.Id,IndustryActivity.Copying)!="","copies cannot be copied");Check(world.InstallIndustry(copy.Id,IndustryActivity.Manufacturing,4)!="","excess copy runs rejected");Supply(ammo,false,3);Check(world.InstallIndustry(copy.Id,IndustryActivity.Manufacturing,3)=="","finite copy manufacturing installs");job=world.Industry.Jobs.Last();job.FinishUtc=DateTime.UtcNow.AddSeconds(-1);world.DeliverIndustry(job.Id);Check(!world.Industry.Blueprints.Contains(copy),"exhausted copy disappears after delivery");
  Supply(ammo,false,1);world.InstallIndustry(bp.Id,IndustryActivity.Manufacturing);job=world.Industry.Jobs.Last();var stock=new Dictionary<string,decimal>(world.Hangar);before=world.Balance;Check(world.CancelIndustry(job.Id)==""&&bp.LockedJob=="","cancellation releases blueprint");Check(world.Balance==before&&stock.All(m=>world.Hangar[m.Key]==m.Value),"cancellation does not refund consumed materials or fee");Check(world.DeliverIndustry(job.Id)!="","cancelled job cannot deliver");
  world.Hangar["ore"]=250;var re=world.QuoteReprocess(new(){{"ore",250}});Check(re.Error==""&&re.Inputs["ore"]==200&&re.Yield>.69&&re.Yield<.70,"ore uses complete 100-unit batches and multiplicative skill bonuses");Check(world.ReprocessIndustry(new(){{"ore",250}})==""&&world.Hangar["ore"]==50,"reprocessing preserves incomplete batches");Check(world.ReprocessIndustry(new(){{"ore",100}})!="","stale reprocessing selection rejected");world.Hangar["miner"]=1;re=world.QuoteReprocess(new(){{"miner",1}});Check(Math.Abs(re.Yield-.55)<.000001,"scrap yield capped at 55 percent with Scrapmetal Processing V");Check(world.QuoteReprocess(new(){{"ind_34",1}}).Error.Length>0,"refined minerals cannot be reprocessed");world.AgentsState.Standings[world.StationCorporation]=6.67;Check(world.QuoteReprocess(new(){{"miner",1}}).Tax==0,"station standings remove withholding tax at 6.67");
  var weak=new DemoWorld();weak.NewGame(0);weak.Credits=100000;var wbp=weak.Industry.Blueprints.First(b=>b.Item=="miner");foreach(var m in recipes["miner"].Minerals)weak.Hangar[m.Key]=10000;Check(weak.InstallIndustry(wbp.Id,IndustryActivity.Manufacturing).Length>0,"build requires trained industry skills");
  int old=world.IndustrySlots(true);Check(old==11&&world.IndustrySlots(false)==11,"skill-based manufacturing and research slot maxima are 11");
  var unit=new IndustryRecipe37{Native=new(){{"ind_34",1},{"ind_35",31}},Minerals=new(){{"ind_34",1},{"ind_35",31}}};var rounded=IndustryCatalog37.Materials(unit,false,100,10,1);Check(rounded["ind_34"]==100&&rounded["ind_35"]==2790,"material rounding occurs per whole job with one-per-run floor");
  Supply(ammo,false,1);world.InstallIndustry(bp.Id,IndustryActivity.Manufacturing);job=world.Industry.Jobs.Last();job.FinishUtc=DateTime.UtcNow.AddSeconds(-1);
  string? oldDir=Environment.GetEnvironmentVariable("STARLIGHT_SAVE_DIR");string dir=Path.Combine(Path.GetTempPath(),"ss-industry37-"+Guid.NewGuid().ToString("N"));Environment.SetEnvironmentVariable("STARLIGHT_SAVE_DIR",dir);
  try{world.Save();Check(File.Exists(DemoWorld.SavePath),"save file written");var loaded=new DemoWorld();Check(loaded.Load(),"new industry save loads");Check(loaded.Industry.Jobs.Any(j=>j.Id==job.Id&&j.State=="Ready")&&loaded.Industry.Blueprints.Single(b=>b.Id==bp.Id).LockedJob==job.Id,"offline completion and blueprint locks survive reload");Check(loaded.DeliverIndustry(job.Id)=="","offline job delivers once after reload");var save=JsonNode.Parse(File.ReadAllText(DemoWorld.SavePath))!;save.AsObject().Remove("IndustryState");File.WriteAllText(DemoWorld.SavePath,save.ToJsonString());loaded=new();Check(loaded.Load()&&loaded.Industry.Jobs.Count==0,"Pass 36 legacy save migrates without creating jobs or consuming stock");}finally{Environment.SetEnvironmentVariable("STARLIGHT_SAVE_DIR",oldDir);if(Directory.Exists(dir))Directory.Delete(dir,true);}
  var hull=ItemCatalog.All.First(i=>i.Slot=="ship");world.Hangar[hull.Id]=1;Check(world.AssembleIndustryHull(hull.Id)&&world.Player.CombatHull==hull.Id&&world.Hangar[hull.Id]==0,"manufactured packaged hull can be assembled and boarded");Check(FittingDesignStore.Equipment(world.Player).Count==0,"manufactured hull does not conjure a free starter fitting");
  world.DeliverIndustry(job.Id);Check(world.MoveIndustryBlueprint(bp.Id)==""&&bp.Station=="cargo","unlocked blueprint can be loaded into ship cargo");Check(world.QuoteIndustry(bp.Id,IndustryActivity.Manufacturing).Error.Contains("Deposit"),"cargo blueprint cannot install remotely");world.SystemId="rook";Check(world.MoveIndustryBlueprint(bp.Id)==""&&bp.Station=="rook","blueprint can be physically hauled and deposited at destination");world.SystemId="aster";
  string nativeItem="weapon_487";world.BuyBlueprint(nativeItem);var nativeBp=world.Industry.Blueprints.Last();foreach(var m in recipes[nativeItem].Native)world.Hangar[m.Key]=m.Value+1000;Check(world.InstallIndustry(nativeBp.Id,IndustryActivity.Manufacturing,native:true)=="","native CCP component recipe installs");var nativeJob=world.Industry.Jobs.Last();Check(nativeJob.Inputs.All(m=>recipes[nativeItem].Native[m.Key]==m.Value),"native recipe keeps CCP ME-zero input quantities");world.CancelIndustry(nativeJob.Id);
  world.Hangar["compressed_deepore"]=200;var deep=world.QuoteReprocess(new(){{"compressed_deepore",200}});Check(deep.Error==""&&deep.Outputs.ContainsKey("ind_11399"),"compressed deep ore reprocesses into rare minerals");
  foreach(var m in recipes[nativeItem].Native)world.Hangar[m.Key]=0;string purchase=world.BuyIndustryInputs(nativeBp.Id,true,1);if(purchase.Length>0)Console.WriteLine("PURCHASE RESULT: "+purchase);Check(purchase==""&&recipes[nativeItem].Native.All(m=>world.Hangar.GetValueOrDefault(m.Key)>=m.Value),"buy-missing-materials fills native recipe from actual local market orders");
  weak.Credits=0;foreach(var m in recipes["miner"].Minerals)weak.Hangar[m.Key]=0;Check(weak.BuyIndustryInputs(wbp.Id,false,1)!=""&&weak.Balance==0&&recipes["miner"].Minerals.All(m=>weak.Hangar.GetValueOrDefault(m.Key)==0),"unaffordable material purchase has no partial wallet or inventory changes");
  Check(world.BuyIndustryInputs(nativeBp.Id,true,0)!="","invalid material purchase quantities rejected");
  Console.WriteLine($"Industry Pass 37: {count} checks passed. Products {recipes.Count}, CCP blueprints {IndustryCatalog37.Database.Blueprints.Count}.");
 }
}
